import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"展示站：中国人一天里要办的七件事","description":"","frontmatter":{},"headers":[],"relativePath":"zh/showcase.md","filePath":"zh/showcase.md"}'),r={name:"zh/showcase.md"};function c(i,e,n,l,s,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="展示站-中国人一天里要办的七件事" tabindex="-1">展示站：中国人一天里要办的七件事 <a class="header-anchor" href="#展示站-中国人一天里要办的七件事" aria-label="Permalink to &quot;展示站：中国人一天里要办的七件事&quot;">​</a></h1><p>nanoMuse 是一个智能体，有好几只手。它读写文件、搜网页、跑命令、开浏览器；调用 MCP 服务器和命令行工具；照技能办事；跑在手机上时，还会用手机自己的日历、剪贴板和闹钟——实在没别的办法了，才去动手机屏幕上的 App。<a href="./gui#the-ladder">阶梯</a>规定哪只手先上：技能、CLI 或 MCP 服务器；然后是带着用户登录态的 fetch；然后是应用内浏览器；最后才是屏幕。下面七个案例里，只有一个用到了屏幕。这正是要说明的。</p><p>这里没有一处会花钱：每一次发送、下单或付款都会停下来等你审批，操作器从不填密码和验证码。这些案例背后是哪些服务、各自在哪里跑过：<a href="./services">services.md</a>。</p><p><strong>轨迹。</strong> 每个案例都链接到实际发生的过程——App 存下来的聊天时间线，或者一份带每个屏幕、每次点按的手机轨迹。标为<em>待跑</em>的案例还没有端到端跑过，那一行写着它在等什么：四个 Tier-1 服务需要所有者的 key 和登录（一把高德 key、一个飞书和一个腾讯会议登录），手机案例需要一台装了这些 App 的 Android 手机。<a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/launch-checklist.md#9-chinese-services-and-the-showcase-p0" target="_blank" rel="noreferrer">发布清单</a>在跟踪它们。</p><h2 id="_1-a-business-trip-in-one-sentence" tabindex="-1">1. 一句话安排一趟出差 <a class="header-anchor" href="#_1-a-business-trip-in-one-sentence" aria-label="Permalink to &quot;1. 一句话安排一趟出差 {#_1-a-business-trip-in-one-sentence}&quot;">​</a></h2><blockquote><p>明天要去上海开会，下午两点在虹桥附近。帮我看看北京到上海上午出发、下午一点前能到虹桥的高铁，挑一班合适的；查一下从家到北京南站几点得出发；把出发时间写进日历，车次发到飞书的「出差」群。另外记住：我坐高铁只坐二等座、靠窗。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>skills</code></td><td>读 <code>train-tickets</code>：查票走 12306 服务器，只在被明确要求时才在手机上订</td></tr><tr><td><code>remember</code></td><td>二等座、靠窗——一条偏好，下次说到火车时会用上</td></tr><tr><td><code>12306__get-current-date</code> · <code>get-station-code-of-citys</code> · <code>get-station-code-by-names</code> · <code>get-tickets</code></td><td>从服务器拿明天的日期、北京和上海虹桥的车站代码、13:00 前的 G 字头车次及余票和票价；第一次查到的卖完了就再查一次</td></tr><tr><td><code>amap__maps_geo</code> · <code>maps_direction_transit_integrated</code></td><td>家（记住的）→ 北京南站，那个时段：06:40 前出发</td></tr><tr><td><code>calendar</code></td><td>一条出发时间的草稿，带车次和座位，等你确认</td></tr><tr><td><code>shell: lark-cli im +chat-search</code> · <code>im +messages-send --idempotency-key …</code></td><td>「出差」群，那一条消息——正文先出现在审批卡片上</td></tr></tbody></table><p>全程没碰屏幕。哨兵（Sentinel）只问一次，为了那条消息；其余的要么只读，要么在你自己的工作区里。</p><p><strong>轨迹：</strong><a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/traces/case-1-train.md" target="_blank" rel="noreferrer">火车那一半</a>——2026-09-24 在网页版用 12306 服务器录的；模型发现 13:00 前的二等座全卖完了，如实说了，并给出最接近的替代车次，而不是装作有票。高德路线、日历草稿和飞书消息<em>待跑</em>：测试机上需要一把高德 key 和一个飞书登录。</p><h2 id="_2-the-morning-brief" tabindex="-1">2. 早间简报 <a class="header-anchor" href="#_2-the-morning-brief" aria-label="Permalink to &quot;2. 早间简报 {#_2-the-morning-brief}&quot;">​</a></h2><blockquote><p>每个工作日早上 7:30 给我一条简报：今天北京的天气、飞书上的日程和没做完的任务、腾讯会议里今天有哪些会，一条通知就好。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>reminders</code>（一条例程）</td><td><code>weekdays 07:30</code>，App 关着也以通知送达——在手机上，运行时的闹钟为此把它叫醒</td></tr><tr><td><code>amap__maps_weather</code></td><td>北京今天：气温、降雨、空气</td></tr><tr><td><code>shell: lark-cli calendar +agenda --as user</code> · <code>task +get-my-tasks --as user</code></td><td>今天的日程和未完成的任务，用 <code>--jq</code> 精简</td></tr><tr><td><code>shell: tmeet meeting list --compact</code></td><td>今天的会议，带会议号和链接</td></tr><tr><td>通知</td><td>一张卡片；点开进入聊天，看到完整简报</td></tr></tbody></table><p>**轨迹：<em><em><em>待跑</em>——高德 key、飞书和腾讯会议登录。例程和通知这条路本身已经由 App 的测试和模拟器验证过（<a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/archive/android-python-line.md#keeping-it-running" target="_blank" rel="noreferrer">archive/android-python-line.md</a> 里</em>让它一直跑</em>那部分的工作）。</p><h2 id="_3-where-is-my-京东-order" tabindex="-1">3. 我的京东订单到哪了 <a class="header-anchor" href="#_3-where-is-my-京东-order" aria-label="Permalink to &quot;3. 我的京东订单到哪了 {#_3-where-is-my-京东-order}&quot;">​</a></h2><blockquote><p>我上周在京东买的耳机到哪了？</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>browser</code>（手机的 WebView，离屏）</td><td>在后台打开京东的订单页</td></tr><tr><td>登录墙</td><td>智能体停下来：「接管」把真实页面作为底部面板滑上来，你登录一次，「完成」交还——登录态保留在 App 自己的浏览器 profile 里</td></tr><tr><td><code>browser</code> <code>extract</code></td><td>订单，以及它的运单号和快递公司</td></tr><tr><td><code>kuaidi100__query_trace</code>（配置了的话）</td><td>包裹的物流事件；否则用订单页自带的物流列表</td></tr><tr><td>回复</td><td>在哪，预计什么时候到</td></tr></tbody></table><p>第二级——App 里一个带着你登录态的页面——排在任何屏幕之前：京东没有个人 API，但它的网页版不用 App 也能用。配置好快递100，查物流就成了一次工具调用。</p><p>**轨迹：**<em>待跑</em>——一台装了本地版的手机上的京东登录。浏览器后端、接管面板和登录态的保留已经在模拟器上验证过，见 <a href="./browser">browser.md</a>。</p><h2 id="_4-a-budget-table-for-成都-over-the-holiday" tabindex="-1">4. 国庆成都行的预算表 <a class="header-anchor" href="#_4-a-budget-table-for-成都-over-the-holiday" aria-label="Permalink to &quot;4. 国庆成都行的预算表 {#_4-a-budget-table-for-成都-over-the-holiday}&quot;">​</a></h2><blockquote><p>国庆去成都三晚，住春熙路附近。帮我在去哪儿网上看看每晚 400 元左右、评分 4.5 以上的酒店，挑三家做成预算表存到 trips/chengdu-2026-10/budget.md，只看不订。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>browser</code>（电脑上的 Playwright，或手机的 WebView）</td><td>按日期和区域在去哪儿搜酒店，加筛选，读三条列表</td></tr><tr><td><code>files</code></td><td><code>trips/chengdu-2026-10/budget.md</code>——名称、位置、每晚价格、三晚合计、评分</td></tr><tr><td>资源库</td><td>这张表在 App 里作为一个页面打开</td></tr></tbody></table><p>第三级：公开网站，不用登录，在后台浏览，你可以去忙别的。智能体不下单；「只看不订」也正是 <code>browser</code> 工具的哨兵规则对下单和付款按钮的要求。</p><p>**轨迹：**2026-09-24 那次运行见本页末尾的说明。</p><h2 id="_5-book-a-meeting-and-tell-the-group" tabindex="-1">5. 约一个会，告诉群里 <a class="header-anchor" href="#_5-book-a-meeting-and-tell-the-group" aria-label="Permalink to &quot;5. 约一个会，告诉群里 {#_5-book-a-meeting-and-tell-the-group}&quot;">​</a></h2><blockquote><p>下周三下午三点跟设计组开半小时的评审会，用腾讯会议，把会议号发到飞书「设计评审」群。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>calendar</code></td><td>那个时段空着</td></tr><tr><td><code>shell: tmeet meeting create --subject 设计评审 --start 2026-09-30T15:00+08:00 --end 2026-09-30T15:30+08:00</code></td><td>一张审批卡片，带完整命令；返回里有 <code>meeting_code</code> 和 <code>join_url</code></td></tr><tr><td><code>shell: lark-cli im +messages-send --chat-id oc_… --text &quot;…&quot;</code></td><td>群消息，带会议号和链接——正文在第二张卡片上</td></tr><tr><td><code>reminders</code></td><td>提前十分钟</td></tr></tbody></table><p>两个 CLI，两次审批，没打开任何 App。**轨迹：**<em>待跑</em>——测试机上的腾讯会议和飞书登录（<code>tmeet auth login</code>、<code>lark-cli auth login</code>）。</p><h2 id="_6-clipboard-→-calendar-alarm" tabindex="-1">6. 剪贴板 → 日历 + 闹钟 <a class="header-anchor" href="#_6-clipboard-→-calendar-alarm" aria-label="Permalink to &quot;6. 剪贴板 → 日历 + 闹钟 {#_6-clipboard-→-calendar-alarm}&quot;">​</a></h2><blockquote><p>（复制了一条消息：「周五上午10点，海淀区中关村大街1号3层会议室，带上合同」）把剪贴板里的这个安排加到日历，提前一小时给我设个闹钟。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td><code>device__clipboard_read</code></td><td>那段文字（Android 只允许 App 在前台时读剪贴板；不在前台时工具会说明）</td></tr><tr><td><code>device__calendar_create</code></td><td>周五 10:00，地址作为地点，「带上合同」写进备注——第一次会弹 Android 自己的权限对话框</td></tr><tr><td><code>device__alarm_set</code></td><td>周五 09:00，通过时钟 App</td></tr><tr><td><code>amap__maps_geo</code>（可选）</td><td>核对地址，把路上时间加进备注</td></tr></tbody></table><p>手机自己的能力作为 MCP 工具（<a href="./device">device.md</a>）；除了可选的那次地理编码，什么都不离开手机。**轨迹：**<em>待跑</em>——Android 手机上的本地版（设备服务器只在那里跑）。</p><h2 id="_7-a-美团-order-that-stops-before-payment" tabindex="-1">7. 一单美团，停在付款前 <a class="header-anchor" href="#_7-a-美团-order-that-stops-before-payment" aria-label="Permalink to &quot;7. 一单美团，停在付款前 {#_7-a-美团-order-that-stops-before-payment}&quot;">​</a></h2><blockquote><p>用美团给我点一份公司附近的麦当劳板烧鸡腿堡套餐，送到公司，到付款前停下来。</p></blockquote><table tabindex="0"><thead><tr><th>手</th><th>做什么</th></tr></thead><tbody><tr><td>在美团里的 <code>phone_task</code></td><td>搜索、餐厅、套餐、地址；整个过程中胶囊显示当前步骤和「停止」</td></tr><tr><td>哨兵</td><td>点「提交订单」属于 SENSITIVE（<code>sensitive_words</code>）：直接在胶囊上「允许一次」/「拒绝」，Android 手机和托管演示里的手机都一样；聊天卡片带着同一个请求</td></tr><tr><td>停下</td><td>操作器在付款页结束并说明；付款是你的事，在 App 里</td></tr></tbody></table><p>唯一一个在屏幕上做的案例，因为美团没有个人 API，它的网页版又需要 App 的登录。操作器看到和做过的一切都在轨迹里，每次点按都画在对应的截图上。两个模型分工：聊天模型负责计划和汇报（展示站机器上是 <code>deepseek-v4.1-flash</code>，<code>MAIN_MODEL</code>），手的模型读每张截图、决定点哪里（<code>qwen3.8-27b</code>，<code>GUI_MODEL</code>）；访客用自己的 OpenRouter key 时，手用的是 <code>qwen/qwen3.8-27b</code>。</p><p>**轨迹：**<em>待跑</em>——一台装了美团的 Android 手机（x86 模拟器跑不了它）。执行器、胶囊和「停止」已经在模拟器上验证过，见 <a href="./gui">gui.md</a>。</p><h2 id="documented-not-shown" tabindex="-1">写下来了，没有演示 <a class="header-anchor" href="#documented-not-shown" aria-label="Permalink to &quot;写下来了，没有演示 {#documented-not-shown}&quot;">​</a></h2><p>另有四个屏幕案例写在 <code>train-tickets</code> 和 <code>phone-messages</code> 技能里，停在同一个地方——最后一步确认由你来：</p><ul><li>交管12123：查罚单，付款前停下。</li><li>滴滴：填好目的地，「呼叫」前停下。</li><li>12306 App：订票到「提交订单」为止（查票本身已经不需要屏幕了）。</li><li>京东 App：购物车到「结算」为止。</li></ul><h2 id="never-in-public-material" tabindex="-1">绝不出现在公开材料里 <a class="header-anchor" href="#never-in-public-material" aria-label="Permalink to &quot;绝不出现在公开材料里 {#never-in-public-material}&quot;">​</a></h2><p>你要求的话，智能体可以在手机屏幕上读微信，也会有人这么用。但它不会出现在展示站、网站或影片里，支付宝账单、医保和个税也不会——这些服务要么条款禁止自动化，要么数据不该出现在演示里。</p><h2 id="reading-the-trail" tabindex="-1">读懂留下的痕迹 <a class="header-anchor" href="#reading-the-trail" aria-label="Permalink to &quot;读懂留下的痕迹 {#reading-the-trail}&quot;">​</a></h2><p>每一步都是聊天里的一行——<code>12306__get-tickets(…)</code>、<code>shell: lark-cli calendar +agenda --as user</code>、<code>phone_act: tap &quot;提交订单&quot; at (318,742) in 美团</code>——每张审批卡片都说明将要做什么、为什么要问。形象下方的 <code>Activity</code> 保存着审计日志，记着每次调用走的通道；<code>Permissions</code> 显示已有的授权，手机步骤的授权永远只有<em>一次</em>。在你自己的服务器上，<code>nanomuse phone traces</code> 列出每个手机任务，<code>nanomuse phone trace &lt;id&gt; -o trace.html</code> 把其中一个渲染成页面，带操作器看到的每个屏幕和画在上面的每次点按（<a href="./gui#traces">gui.md → 轨迹</a>）。<a href="https://github.com/nano-muse/nanoMuse/tree/main/docs/traces/" target="_blank" rel="noreferrer"><code>docs/traces/</code></a> 下的 Markdown 轨迹是同样的时间线，渲染成便于阅读的样子。</p><p>十一个技能带着这些习惯——<code>feishu</code>、<code>tencent-meeting</code>、<code>amap</code>、<code>kuaidi100</code> 和 <code>train-tickets</code> 对应上面的服务，<code>phone-messages</code> 对应屏幕，<code>trip-plan</code>、<code>meeting-prep</code>、<code>inbox-triage</code>、<code>compare-options</code> 和 <code>weekly-review</code> 是智能体自己的活。App 里的 <code>Skills</code> 列着它们；你自己放一个同名文件夹就能替换掉一个。按 <a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills</a> 格式为其他智能体写的技能，原样放进 <code>&lt;data_dir&gt;/skills</code> 就能用——Larksuite 自己的 <code>lark-*</code> 技能也包括在内。</p>',44)])])}const m=t(r,[["render",c]]);export{b as __pageData,m as default};
